"""Draft for Compulsory Physics, Book 3, Chapters 12 (Electrical Energy and Conservation of Energy) and 13 (Electromagnetic Induction and an Introduction to Electromagnetic Waves), People's Education Press 2019 edition."""
from phy_hs_lib import T, C, N

# ---------------- Chapter 12: Electrical Energy and Conservation of Energy
T("electric_work", "Energy", "procedural",
  "Understand electrical work W = UIt in terms of work done by electrostatic forces on charges. Know that electric power P = UI describes how quickly current does work; calculate electrical energy and electricity costs; and convert between kW·h and J in practical problems.",
  ["Calculate electrical work and power using W = UIt and P = W/t = UI", "Know that electric power describes the rate of doing work, not the amount of work", "Calculate appliance energy use and electricity costs"],
  [("B3.2.5", "exact")],
  pre=[("potential_diff", "hard"), ("current", "hard"), ("J:elec_power", "soft"), ("J:elec_energy", "soft")],
  qs=[
    N("basic", "An appliance operates at 220 V with a current of 0.5 A for 10 min. How much work does the current do in J? (Enter a number only)", "66000",
      "W = UIt = 220 × 0.5 × 600 s = 66000 J. Forgetting to convert 10 min to 600 s gives 1100 J.", "220*0.5*600"),
    C("basic", "Which statement about electric power is correct?", "Electric power describes how quickly current does work", ["A higher electric power always means an appliance uses more electrical energy", "A higher electric power always means a larger current flows through the appliance",
      "Electric power is the amount of work done by current"],
      "P = W/t describes the rate of doing work; energy use also depends on time, W = Pt. Current I = P/U also depends on voltage."),
    N("standard", "An air conditioner rated at 1.5 kW runs 8 h per day for 30 days. If electricity costs 0.5 yuan per kW·h, what is the monthly bill in yuan? (Enter a number only)", "180",
      "Energy use W = Pt = 1.5 kW × 8 h × 30 = 360 kW·h, so the bill is 360 × 0.5 = 180 yuan.", "1.5*8*30*0.5"),
    C("standard", "A bulb labeled \"220 V, 100 W\" is connected to a 110 V circuit. Assuming its filament resistance stays constant, what is its actual power?", "25 W", ["50 W", "100 W", "12.5 W"],
      "R = Uᵣₐₜₑd²/Pᵣₐₜₑd = 484 Ω; Pₐctual = U²/R = 110²/484 = 25 W. Halving the voltage makes the power one-fourth as large, not one-half.",
      verify="110**2/(220**2/100)"),
  ])

T("joule", "Energy", "procedural",
  "Know that current through a conductor produces heat according to Q = I²Rt (Joule's law). Distinguish purely resistive circuits from non-ohmic circuits such as motors; UIt is the total electrical energy, while I²Rt is only the part converted into internal energy.",
  ["Calculate heat and thermal power using Q = I²Rt", "Distinguish the relationship between electrical work and heat in purely resistive and non-ohmic circuits", "Calculate a motor's mechanical power, Pₘₑcₕ = UI − I²R"],
  [("B3.2.5", "exact")],
  pre=[("electric_work", "hard"), ("ohm_law", "hard"), ("J:joule", "soft")],
  qs=[
    N("basic", "A 10 Ω resistor carries a current of 2 A. How much heat, in J, is produced in 30 s? (Enter a number only)", "1200",
      "Q = I²Rt = 2² × 10 × 30 = 1200 J. Omitting the square on the current gives 600 J.", "2**2*10*30"),
    C("basic", "A motor has voltage U across it, current I through it, and coil resistance R. What is the rate of heat production in its coil?", "I²R", ["UI", "U²/R", "UI − I²R"],
      "Joule's law, Pₕₑₐₜ = I²R, applies in any circuit. UI is the total electrical power, and UI − I²R is mechanical power; U²/R applies only to purely resistive circuits."),
    N("standard", "A motor connected to 220 V draws 5 A, and its coil resistance is 2 Ω. What is its mechanical output power in W? (Enter a number only)", "1050",
      "Total power UI = 220 × 5 = 1100 W; heat power I²R = 25 × 2 = 50 W; mechanical power = 1100 − 50 = 1050 W. Using U²/R for heat gives 220²/2 = 24,200 W, far greater than the total power of 1,100 W, which is clearly unreasonable.", "220*5-5**2*2"),
    C("advanced", "A motor rated at 6 V has a coil resistance of 0.5 Ω and normally draws 1 A. If it is stalled and cannot turn, what current flows through it?", "12 A", ["1 A", "11 A", "5.5 A"],
      "When stalled, the motor produces no mechanical output and behaves as a pure resistor: I = U/R = 6/0.5 = 12 A. The large current causes intense heating and may burn out the coil. Mistakenly using the 5.5 V back EMF during normal operation gives 5.5/0.5 = 11 A.", verify="6/0.5"),
  ])

T("household", "Interdisciplinary Practice", "application",
  "Understand that a household circuit includes a live wire, neutral wire, electricity meter, circuit breaker, outlets, and appliances connected in parallel. Estimate total household power and current, and learn electrical safety measures such as grounding.",
  ["Know that household appliances are connected in parallel and switches are placed in the live wire", "Explain why short circuits and excessive total power cause excessive current", "Understand the protective role of grounding in three-prong outlets and estimate the maximum power allowed by a circuit breaker"],
  [("B3.2.6", "exact")],
  pre=[("joule", "hard"), ("series_parallel", "soft"), ("J:home_circuit", "hard"), ("J:safety", "soft")],
  qs=[
    C("basic", "How are appliances connected to one another in a household circuit?", "In parallel", ["In series", "High-power appliances in series and low-power appliances in parallel", "Appliances in the same room in series"],
      "Each appliance is rated for 220 V. In parallel, each has 220 V across it and operates independently. In a series circuit, all appliances stop working if one is disconnected."),
    N("basic", "A household uses a 1.2 kW air conditioner, a 0.8 kW electric kettle, and a 0.2 kW television at the same time. If the household voltage is 220 V, what is the current in the main line in A? (Enter a number only)", "10",
      "Total power P = 1200 + 800 + 200 = 2200 W, so I = P/U = 2200/220 = 10 A. Appliances are in parallel, so total power is the sum of their powers.", "2200/220"),
    C("standard", "A washing machine uses a three-prong outlet, and its metal casing is grounded. What is the main purpose of grounding?", "If the casing leaks current, it directs the current into the ground and prevents electric shock", ["It increases the operating current to make the washer spin faster", "It provides a higher operating voltage", "It reduces the washer's energy use"],
      "If the live wire touches a grounded metal casing, current flows through the low-resistance ground wire into the earth, keeping the casing at earth potential. This prevents shock and can cause the circuit breaker to trip."),
    N("standard", "A household circuit breaker is rated at 16 A, and the household voltage is 220 V. What is the maximum total power of appliances that can operate simultaneously, in W? (Enter a number only)", "3520",
      "P = UI = 220 × 16 = 3520 W. Above this total power, the main-line current exceeds 16 A and the circuit breaker trips.", "220*16"),
  ])

T("emf", "Energy", "conceptual",
  "Understand that a source converts other forms of energy into electrical energy through work done by non-electrostatic forces. Electromotive force E = Wₙₒₙ/q describes this conversion capability; distinguish electromotive force from terminal voltage and understand internal resistance.",
  ["Understand the physical meaning and defining equation of electromotive force, E = W/q", "Distinguish electromotive force from terminal voltage", "Calculate the electrical energy supplied by a source using W = EIt"],
  [("B3.2.4", "exact")],
  pre=[("potential_diff", "hard"), ("current", "hard"), ("electric_work", "soft")],
  qs=[
    C("basic", "Which statement about a source's electromotive force is correct?", "It describes the source's ability to convert other forms of energy into electrical energy", ["It equals the voltage across the source whenever it is connected to a circuit", "It describes the magnitude of the current supplied by the source", "It is the amount of work done by electrostatic forces to move charge"],
      "Electromotive force is determined by the source and is the work done by non-electrostatic forces to move a unit positive charge. Terminal voltage equals electromotive force only in an open circuit."),
    N("basic", "Non-electrostatic forces inside a battery do 3 J of work to move 2 C of positive charge from the negative terminal to the positive terminal. What is the battery's electromotive force in V? (Enter a number only)", "1.5",
      "E = W/q = 3/2 = 1.5 V.", "3/2"),
    C("standard", "A dry cell has an electromotive force of 1.5 V. What does this mean?", "Non-electrostatic forces inside the cell do 1.5 J of work for every 1 C of charge they move", ["The voltage across the cell is 1.5 V in every circuit", "The cell converts 1.5 J of chemical energy into electrical energy each second",
      "The external circuit uses 1.5 J of electrical energy for every 1 C of charge"],
      "E = W/q means 1.5 J of electrical energy is converted per 1 C of charge moved, independent of time. When connected to a circuit, internal resistance causes a voltage drop, so terminal voltage is less than 1.5 V and the external circuit uses less than 1.5 J per coulomb."),
    N("standard", "A 12 V battery supplies a constant current of 5 A for 2 min. How much work, in J, do the non-electrostatic forces inside the battery do? (Enter a number only)", "7200",
      "q = It = 5 × 120 = 600 C, so W = Eq = 12 × 600 = 7200 J.", "12*5*120"),
  ])

T("closed_circuit", "Energy", "procedural",
  "Apply Ohm's law for a closed circuit, I = E/(R+r), and understand how E = Uₑₓₜ + Uᵢₙₜ relates to conservation of energy. Know how terminal voltage changes with external resistance and understand open- and short-circuit conditions.",
  ["Calculate current and terminal voltage using I = E/(R+r) and U = E − Ir", "Know that terminal voltage increases as external resistance increases and that U = E in an open circuit", "Know that a short circuit has current I = E/r and zero terminal voltage"],
  [("B3.2.4", "exact")],
  pre=[("emf", "hard"), ("series_parallel", "hard"), ("ohm_law", "hard"), ("J:ohm_sp", "soft")],
  qs=[
    N("basic", "A source has electromotive force E = 6 V and internal resistance r = 1 Ω. Its external circuit contains only a resistor R = 5 Ω. What is the current in A? (Enter a number only)", "1",
      "I = E/(R + r) = 6/(5 + 1) = 1 A. Forgetting to include internal resistance gives 1.2 A.", "6/(5+1)"),
    C("basic", "A source's electromotive force and internal resistance remain constant. What happens to terminal voltage as external resistance increases?", "It increases", ["It decreases", "It stays the same", "It first increases and then decreases"],
      "As external resistance increases, total resistance increases and I = E/(R + r) decreases. The internal voltage drop Ir decreases, so terminal voltage U = E − Ir increases; in an open circuit, U = E."),
    N("standard", "A battery has a terminal voltage of 3 V when it is disconnected from a circuit. When a 5.5 Ω resistor is connected, its terminal voltage becomes 2.75 V. What is the battery's internal resistance in Ω? (Enter a number only)", "0.5",
      "E = 3 V; I = U/R = 2.75/5.5 = 0.5 A; internal voltage = 3 − 2.75 = 0.25 V; r = 0.25/0.5 = 0.5 Ω.", "(3-2.75)/(2.75/5.5)"),
    C("standard", "A battery with internal resistance r and electromotive force E has its terminals connected directly by a wire with negligible resistance. What happens?", "Terminal voltage is 0 and current is E/r", ["Terminal voltage is E and current is 0", "Terminal voltage is E and current is E/r", "Terminal voltage is 0 and current is 0"],
      "The external resistance is R = 0, so I = E/r (a very large current) and terminal voltage U = E − Ir = 0. The battery heats rapidly and may be damaged. Terminal voltage E occurs in an open circuit."),
  ])

T("circuit_dynamic", "Energy", "reasoning",
  "Analyze dynamic problems caused by resistance changes in a closed circuit using the sequence \"local resistance → total resistance → total current → terminal voltage → individual components.\" Calculate a source's output power and know that it is maximized when external resistance equals internal resistance.",
  ["Analyze how meter readings change as a sliding resistor's resistance changes", "Know that Pₒᵤₜ = E²R/(R+r)² and output power is maximized at E²/(4r) when R = r", "Use the equivalent-internal-resistance method to find the maximum power of a variable resistor"],
  [("B3.2.4", "exact"), ("B3.2.5", "inferred")],
  pre=[("closed_circuit", "hard"), ("series_parallel", "hard"), ("electric_work", "hard")],
  math=[("cnm_h022", "Write output power as E²/(R + r²/R + 2r) and use the basic inequality to show it is maximized when R = r.")],
  qs=[
    C("basic", "A source (electromotive force E, internal resistance r), fixed resistor R₁, and sliding resistor R₂ are connected in series. An ammeter is in series, and a voltmeter measures terminal voltage. How do the readings change when the slider increases R₂?",
      "The ammeter reading decreases and the voltmeter reading increases", ["Both readings increase", "The ammeter reading increases and the voltmeter reading decreases", "Both readings decrease"],
      "R₂ increases → total resistance increases → I = E/(R_total + r) decreases → internal voltage drop Ir decreases → terminal voltage U = E − Ir increases."),
    N("basic", "A source has electromotive force E = 6 V and internal resistance r = 2 Ω. Its external resistance is adjustable. What is the maximum output power in W? (Enter a number only)", "4.5",
      "Output power is maximized when R = r = 2 Ω: Pmax = E²/(4r) = 36/8 = 4.5 W. At this point, source efficiency is only 50%.", "6**2/(4*2)"),
    C("standard", "A source with E = 12 V and r = 2 Ω is connected in series with a fixed resistor R₀ = 3 Ω and a sliding resistor R ranging from 0 to 10 Ω. What value of R maximizes the power dissipated by R₀?",
      "0 Ω", ["2 Ω", "5 Ω", "10 Ω"],
      "R₀ is fixed, and P₀ = I²R₀, so its power is greatest when I is greatest. This requires the total resistance to be minimized, so R = 0. The rule \"power is maximized when R = r\" applies only to the variable resistor's own power, not a fixed resistor."),
    N("advanced", "A source with E = 12 V and r = 2 Ω is connected in series with a fixed resistor R₀ = 3 Ω and a sliding resistor R ranging from 0 to 10 Ω. What is the maximum power dissipated by R, in W? (Enter a number only)", "7.2",
      "Include R₀ in the source's internal resistance: r' = R₀ + r = 5 Ω. When R = 5 Ω (within the 0–10 Ω range), Pmax = E²/(4r') = 144/20 = 7.2 W.", "12**2/(4*(3+2))"),
  ])

T("exp_emf", "Interdisciplinary Practice", "procedural",
  "Use U = E − Ir with a voltmeter, ammeter, and sliding resistor to measure a dry cell's electromotive force and internal resistance. Find E and r from the vertical intercept and slope of a U–I graph, and analyze systematic errors caused by the circuit arrangement.",
  ["Draw the measurement circuit and explain its principle", "Find E and r from the intercept and slope of a U–I graph, accounting for the axis origin", "Analyze systematic error caused by current through the voltmeter"],
  [("B3.X.5", "exact"), ("B3.2.4", "exact")],
  pre=[("closed_circuit", "hard"), ("exp_multimeter", "soft"), ("meter_modify", "soft"), ("J:measure_r", "soft")],
  math=[("cnm_202", "A U–I graph is the graph of a linear function; its vertical intercept and slope correspond to E and r, respectively.")],
  qs=[
    C("basic", "In an experiment to measure a dry cell's electromotive force and internal resistance, a U–I graph is plotted from several (I, U) measurements. What do the vertical intercept and the absolute value of the slope represent, respectively?", "Electromotive force E; internal resistance r", ["Internal resistance r; electromotive force E", "Short-circuit current; electromotive force E", "Electromotive force E; short-circuit current"],
      "From U = E − Ir, U is a linear function of I: the vertical intercept (at I = 0) is E, and the absolute value of the slope is r."),
    N("basic", "Two measurements for a dry cell are I₁ = 0.10 A, U₁ = 1.45 V and I₂ = 0.50 A, U₂ = 1.25 V. What is the cell's internal resistance in Ω? (Enter a number only)", "0.5",
      "r = |ΔU/ΔI| = (1.45 − 1.25)/(0.50 − 0.10) = 0.5 Ω.", "round((1.45-1.25)/(0.50-0.10),2)"),
    C("standard", "In an experimental circuit, a voltmeter is connected directly across a battery and an ammeter is placed in series with the sliding-resistor branch, measuring the current through that resistor. The ammeter's internal resistance is negligible, but the voltmeter's is finite. Which result is measured?",
      "Eₘₑₐₛ < Eₜᵣᵤₑ, rₘₑₐₛ < rₜᵣᵤₑ", ["Eₘₑₐₛ = Eₜᵣᵤₑ, rₘₑₐₛ > rₜᵣᵤₑ", "Eₘₑₐₛ < Eₜᵣᵤₑ, rₘₑₐₛ > rₜᵣᵤₑ", "Eₘₑₐₛ > Eₜᵣᵤₑ, rₘₑₐₛ > rₜᵣᵤₑ"],
      "The voltmeter draws current, so the ammeter reads less than the actual current through the battery. At U = 0 (short circuit), the voltmeter draws no current and Iₘₑₐₛ = Iₜᵣᵤₑ. The horizontal intercept is unchanged, but the vertical intercept Eₘₑₐₛ is too small, so the absolute slope rₘₑₐₛ = Eₘₑₐₛ/Iₛₕₒᵣₜ is too small."),
    N("advanced", "To make a graph clearer, a student starts the vertical axis of a U–I graph at 1.00 V. The line passes through (0, 1.48 V) and (0.40 A, 1.00 V). What is the battery's internal resistance in Ω? (Enter a number only)", "1.2",
      "When the vertical axis does not start at 0, the horizontal intercept is not the short-circuit current, so internal resistance cannot be found from E divided by that intercept. Instead, use the slope: r = ΔU/ΔI = (1.48 − 1.00)/0.40 = 1.2 Ω.", "round((1.48-1.00)/0.40,2)"),
  ])

T("energy_sustain", "Interdisciplinary Practice", "application",
  "Know that energy is conserved but energy conversions have a direction, making dissipated internal energy difficult to reuse. Learn how hydropower, wind, solar, and nuclear energy are used; distinguish renewable from nonrenewable sources; and make simple energy-saving estimates.",
  ["Distinguish renewable and nonrenewable energy sources", "Explain why conservation of energy is consistent with the need to conserve energy resources", "Estimate practical quantities such as hydropower output and energy savings"],
  [("B3.4.2", "exact"), ("B3.4.3", "exact"), ("B3.4.1", "exact")],
  pre=[("energy_conservation", "hard"), ("joule", "soft"), ("J:energy_now", "hard"), ("J:new_energy", "soft")],
  qs=[
    C("basic", "Which of the following is a renewable energy source?", "Hydropower", ["Coal", "Petroleum", "Natural gas"],
      "Hydropower is replenished through the water cycle; coal, petroleum, and natural gas are nonrenewable."),
    C("basic", "The law of conservation of energy says energy cannot be destroyed. Why, then, do people emphasize conserving energy resources?", "Energy conversions have a direction, and dissipated internal energy cannot be reused spontaneously",
      ["Used energy disappears, so the total amount keeps decreasing", "The law of conservation of energy does not apply to macroscopic processes", "Internal energy can spontaneously turn entirely back into electrical energy for reuse"],
      "The total amount of energy remains constant, but the energy available for convenient human use becomes lower quality. Internal energy dissipated into the environment cannot spontaneously gather together to be reused."),
    N("standard", "A 100 W incandescent bulb is replaced with a 20 W LED bulb of similar brightness. Both are used 5 h per day. Taking a year as 365 days, how much electricity in kW·h is saved per year? (Enter a number only)", "146",
      "The power saved is (100 − 20) W = 0.08 kW, so the energy saved is 0.08 × 5 × 365 = 146 kW·h.", "(100-20)/1000*5*365"),
    N("standard", "A small hydroelectric station has a 50 m drop between upstream and downstream. Water flows through the turbine at 20 m³/s, and 80% of its gravitational potential energy is converted to electrical energy. What is the station's output power in kW? (Water density: 1×10³ kg/m³; g = 10 m/s²; enter a number only)", "8000",
      "The water mass per second is m = ρV = 2×10⁴ kg. Its gravitational potential energy decreases by mgh = 2×10⁴ × 10 × 50 = 1×10⁷ J, so P = 0.8 × 1×10⁷ W = 8×10⁶ W = 8000 kW.", "1000*20*10*50*0.8/1000"),
  ])

# ---------------- Chapter 13: Electromagnetic Induction and an Introduction to Electromagnetic Waves
T("magnetic_field", "Motion and Interactions", "conceptual",
  "Know that magnets and currents produce magnetic fields and that magnetic fields exert forces on magnetic poles and currents. Use magnetic field lines to represent fields, and learn the field-line patterns of bar and horseshoe magnets as well as the characteristics of Earth's magnetic field.",
  ["Know how the direction of a magnetic field is defined", "Know that magnetic field lines are closed, do not intersect, and show field strength by their spacing", "Understand the distribution of Earth's magnetic field and that its magnetic poles are roughly opposite its geographic poles"],
  [("B3.3.2", "exact"), ("B3.3.1", "inferred")],
  pre=[("J:magnet", "hard"), ("field_lines", "soft")],
  qs=[
    C("basic", "By convention, which direction is the magnetic-field direction at a point?", "The direction in which the north pole of a stationary compass needle points", ["The direction in which the south pole of a stationary compass needle points", "The direction of the force on a current-carrying wire at that point", "The direction indicated by the spacing of magnetic field lines"],
      "The magnetic-field direction is defined as the direction in which a stationary compass needle's north pole points (or the direction of the force on its north pole). The force on a current-carrying wire is perpendicular to the magnetic field, not its direction."),
    C("basic", "Which statement about the magnetic field lines around a bar magnet is correct?", "They form closed loops, going from north to south outside the magnet and from south to north inside it", ["They start at the north pole and end at the south pole, forming open curves", "They go from south to north outside the magnet and in the opposite direction inside it", "They are real curves in the magnetic field and may intersect"],
      "Magnetic field lines are a model. They go from north to south outside the magnet and from south to north inside it, forming closed loops. This differs from electric field lines."),
    C("standard", "A suspended compass needle always points north when at rest. What does this show?", "Earth's magnetic south pole is near the geographic North Pole", ["Earth's magnetic north pole is near the geographic North Pole", "Earth's magnetic and geographic poles coincide exactly", "The magnetic field above the equator points vertically downward"],
      "Unlike magnetic poles attract. Since a compass needle's north pole points north, Earth's magnetic south pole is near the geographic North Pole. The magnetic and geographic poles do not coincide (there is magnetic declination), and near the equator the field is approximately horizontal and points from south to north."),
    C("standard", "Which statement correctly describes the spacing of magnetic field lines and field strength?", "The field is stronger where the lines are denser, and no two field lines intersect", ["There is no magnetic field in the empty spaces between lines", "The tangent to a field line is perpendicular to the field direction at that point", "The field is weaker where the lines are denser"],
      "The spacing of field lines indicates field strength, and their tangent gives the field direction. If two lines intersected, the field would have two directions at the intersection, which is impossible. A magnetic field exists even where no lines are drawn."),
  ])

T("ampere_rule", "Motion and Interactions", "reasoning",
  "Know that Oersted's experiment showed that a current produces a magnetic field. Use the right-hand rule (right-hand screw rule) to determine the field direction around a straight current, a current loop, and a current-carrying solenoid, and determine simple superpositions of magnetic fields.",
  ["Use the right-hand rule to determine the magnetic field around a straight current", "Determine the field inside a current loop or solenoid and identify its north and south poles", "Determine the direction of the combined fields from two straight currents"],
  [("B3.3.2", "exact"), ("B3.3.1", "inferred")],
  pre=[("magnetic_field", "hard"), ("current", "soft"), ("J:current_mag", "hard")],
  qs=[
    C("basic", "A long, straight wire is vertical, with current flowing upward. Viewed from above, what is the direction of the magnetic field lines around the wire?", "Counterclockwise concentric circles", ["Clockwise concentric circles", "Rays directed outward from the wire", "Straight lines pointing upward"],
      "By the right-hand rule, point your right thumb in the current's direction (upward); the curl of your fingers gives the field-line direction, which is counterclockwise from above. The field lines are closed concentric circles perpendicular to the current."),
    C("basic", "A horizontal circular wire carries current counterclockwise when viewed from above. What is the magnetic-field direction along the central axis inside the loop?", "Vertically upward", ["Vertically downward", "Horizontally to the right", "Tangent to the loop"],
      "For a current loop, curl the fingers of your right hand in the current's direction; your thumb points along the field inside the loop. A counterclockwise current viewed from above gives an upward direction."),
    C("standard", "A vertical current-carrying solenoid has clockwise current when viewed from above. Which statement about the solenoid is correct?", "Its lower end is the north pole", ["Its upper end is the north pole", "Both ends are north poles", "There is no field inside the solenoid; the field is only outside"],
      "Clockwise current viewed from above gives a downward field inside the solenoid. The field exits at the lower end, making it the north pole. The field inside a current-carrying solenoid is strong; outside, it resembles that of a bar magnet."),
    C("standard", "Two long, parallel wires perpendicular to the page carry equal currents in the same direction. What is the net magnetic flux density midway between them?", "Zero", ["Twice the flux density from one wire at that point", "Nonzero, directed along the line connecting the wires", "Half the flux density from one wire at that point"],
      "The wires produce equal magnetic flux densities in opposite directions at the midpoint, so they cancel. If the currents were opposite, the fields would add to twice the field from one wire, in a direction perpendicular to the line between them."),
  ])

T("b_field", "Motion and Interactions", "conceptual",
  "Know that magnetic flux density B describes a magnetic field's strength and direction, with B = F/(IL) for a wire perpendicular to the field, measured in teslas (T). B is a vector determined by the field itself, and magnetic flux densities add according to the parallelogram rule.",
  ["Calculate magnetic flux density using B = F/(IL)", "Understand that B is determined by the field, independently of F, I, and L, and that F = 0 does not necessarily mean B = 0", "Add two perpendicular magnetic flux-density vectors"],
  [("B3.3.2", "exact")],
  pre=[("magnetic_field", "hard"), ("e_field", "soft"), ("ampere_rule", "soft")],
  math=[("cnm_174", "Use the Pythagorean theorem to combine two perpendicular magnetic flux-density vectors.")],
  qs=[
    N("basic", "A 0.2 m straight wire carries 5 A perpendicular to a uniform magnetic field and experiences a force of 0.1 N. What is the magnetic flux density in T? (Enter a number only)", "0.1",
      "B = F/(IL) = 0.1/(5 × 0.2) = 0.1 T.", "0.1/(5*0.2)"),
    C("basic", "A short current-carrying wire at a point experiences no magnetic force. What can be concluded?", "The magnetic flux density may be nonzero; the wire may be parallel to the field", ["The field must be perpendicular to the wire", "The field is weak and the wire must be perpendicular to it", "The magnetic flux density must be zero because B = F/(IL)"],
      "B = F/(IL) applies only when the wire is perpendicular to the field. A wire parallel to the field experiences no force, but the magnetic flux density is not necessarily zero; B is determined by the field itself."),
    C("standard", "At a point, two perpendicular magnetic fields have flux densities of 3 mT and 4 mT. What is the magnitude of the resultant magnetic flux density?", "5 mT", ["7 mT", "1 mT", "3.5 mT"],
      "Magnetic flux density is a vector. For perpendicular vectors, the magnitude is √(3² + 4²) = 5 mT. Adding directly to get 7 mT ignores their directions.", verify="sqrt(3**2+4**2)"),
    C("standard", "Which statement about magnetic flux density is correct?", "B = F/(IL) is a ratio definition, and B is determined by the magnetic field itself", ["B is proportional to F and inversely proportional to IL", "B points in the direction of the force on a short current-carrying wire", "B is numerically equal to the force on any wire with a current-length product of 1 A·m, regardless of its orientation"],
      "A quantity defined as a ratio does not depend on its numerator and denominator. B points in the direction of a compass needle's north pole and is perpendicular to the force on a current-carrying wire; F = BIL only when the wire is perpendicular to the field."),
  ])

T("flux", "Motion and Interactions", "procedural",
  "Know that magnetic flux Φ = BS represents the number of magnetic field lines passing through an area and is measured in webers (Wb). When the plane is not perpendicular to the field, Φ = BS⊥. Calculate magnetic flux and its change, and know that flux is independent of the number of coil turns.",
  ["Calculate magnetic flux for a perpendicular plane using Φ = BS", "Calculate flux when the plane is angled to the field using Φ = BS sin θ", "Calculate the change in flux when a coil is flipped"],
  [("B3.3.3", "exact")],
  pre=[("b_field", "hard"), ("force_decompose", "soft")],
  math=[("cnm_276", "When the plane is angled to the field, use trigonometry to find the effective area perpendicular to the field.")],
  qs=[
    N("basic", "A coil with an area of 0.04 m² is perpendicular to a uniform magnetic field with a flux density of 0.5 T. What is the magnetic flux through the coil in Wb? (Enter a number only)", "0.02",
      "Φ = BS = 0.5 × 0.04 = 0.02 Wb.", "0.5*0.04"),
    C("basic", "A rectangular coil in a uniform magnetic field is rotated from a position where its plane is perpendicular to the field to one where it is parallel. How does the flux through the coil change?", "It decreases from its maximum to zero", ["It stays the same", "It increases from zero to its maximum", "It changes from its maximum to the maximum in the opposite direction"],
      "When the plane is perpendicular, Φ = BS is at its maximum. When it is parallel, no field lines pass through the plane, so Φ = 0."),
    N("standard", "A coil with an area of 0.5 m² is in a uniform field with a flux density of 0.4 T. The plane of the coil makes a 30° angle with the field. What is the magnetic flux in Wb? (sin 30° = 0.5; enter a number only)", "0.1",
      "The effective area is S⊥ = S sin 30° = 0.25 m², so Φ = BS⊥ = 0.4 × 0.25 = 0.1 Wb. Using cos 30° incorrectly gives about 0.17 Wb.", "round(0.4*0.5*sin(radians(30)),3)"),
    N("advanced", "A 100-turn coil with an area of 0.5 m² is initially perpendicular to a uniform magnetic field with a flux density of 0.2 T. It is flipped through 180°. What is the magnitude of the change in magnetic flux through the coil in Wb? (Enter a number only)", "0.2",
      "Magnetic flux is a scalar with a sign: initially Φ₁ = BS = 0.1 Wb; after flipping, the flux is in the opposite direction, Φ₂ = −0.1 Wb, so |ΔΦ| = 0.2 Wb. Flux is independent of the number of turns; do not multiply by 100.", "2*0.2*0.5"),
  ])

T("em_induction", "Motion and Interactions", "reasoning",
  "Learn about Faraday's investigations that led to the discovery of electromagnetic induction. Know that an induced current is produced when the magnetic flux through a closed circuit changes; determine whether a current is induced in different situations and learn applications of electromagnetic induction.",
  ["State the condition for producing an induced current", "Determine whether an induced current is produced by checking whether magnetic flux changes", "Distinguish closed circuits from open circuits"],
  [("B3.3.3", "exact")],
  pre=[("flux", "hard"), ("ampere_rule", "soft"), ("J:induction", "hard")],
  qs=[
    C("basic", "What condition is required to produce an induced current?", "The magnetic flux through a closed circuit changes", ["A conductor moves in a magnetic field", "A closed circuit is in a magnetic field", "The magnetic flux through a closed circuit is large"],
      "Regardless of the cause, a changing magnetic flux through a closed circuit produces an induced current. A magnetic field or large flux alone is not enough; the flux must change."),
    C("basic", "A rectangular closed coil is placed in a uniform magnetic field large enough to contain it, with its plane perpendicular to the field. The coil moves without leaving the field. Is there an induced current?", "No; the magnetic flux through the coil does not change",
      ["Yes; every side of the coil cuts magnetic field lines", "Yes; the coil is moving in a magnetic field", "Yes; the magnetic flux through the coil is at its maximum"],
      "During translation, B, S, and the angle remain constant, so Φ does not change and no current is induced. Whether a conductor \"cuts field lines\" must be considered for the flux through the entire closed circuit; effects from the two pairs of sides cancel."),
    C("standard", "Coil A is connected in series with a source, switch, and sliding resistor. Coil B forms a closed circuit with a sensitive galvanometer, and A is inside B. In which situation does the galvanometer needle not deflect?", "After the switch is closed, the slider remains stationary", ["At the instant the switch is closed", "At the instant the switch is opened", "After the switch is closed, the slider is moved to the right"],
      "Closing or opening the switch, or moving the slider, changes the current in A and thus the flux through B, inducing a current in B. Once the current is steady, the flux is constant and the needle does not deflect."),
    C("standard", "A conducting rod moves perpendicular to a uniform magnetic field, cutting field lines, but its ends are not connected in a circuit. Which statement is correct?", "It cannot produce a sustained induced current because the circuit is open", ["It produces a sustained current because the rod cuts field lines", "It produces a sustained current, but the current is small", "It produces a sustained current whose direction is determined by the field"],
      "An induced current requires a closed circuit. In an open circuit, charge cannot flow continuously and instead accumulates at the rod's ends. Cutting field lines is only one way to change flux through a circuit."),
  ])

T("em_wave", "Motion and Interactions", "conceptual",
  "Learn how Maxwell predicted electromagnetic waves and Hertz confirmed them experimentally. Know that electromagnetic waves travel at the speed of light in a vacuum and satisfy c = λf. Learn the electromagnetic spectrum ordered by wavelength and applications of radio waves, infrared, ultraviolet, and other waves.",
  ["Know the prediction and experimental confirmation of electromagnetic waves and that electromagnetic fields are physical", "Calculate electromagnetic wavelength or frequency using c = λf", "Order the electromagnetic spectrum by wavelength and give examples of applications"],
  [("B3.3.4", "exact"), ("B3.3.5", "exact"), ("B3.3.6", "inferred")],
  pre=[("J:em_wave", "hard"), ("em_induction", "soft"), ("magnetic_field", "soft"), ("J:broadcast", "soft")],
  qs=[
    C("basic", "Who first confirmed the existence of electromagnetic waves experimentally?", "Hertz", ["Maxwell", "Faraday", "Oersted"],
      "Maxwell predicted electromagnetic waves theoretically, and Hertz confirmed them experimentally. Faraday discovered electromagnetic induction, and Oersted discovered the magnetic effect of electric current."),
    N("basic", "An FM radio station transmits electromagnetic waves at 100 MHz. What is their wavelength in a vacuum in m? (c = 3×10⁸ m/s; enter a number only)", "3",
      "λ = c/f = 3×10⁸ / (1×10⁸ Hz) = 3 m. Treating 100 MHz as 100 Hz gives the incorrect result 3×10⁶ m.", "3e8/100e6"),
    C("standard", "Which statement about electromagnetic waves is correct?", "They can travel through a vacuum, where their speed is the speed of light", ["They require a medium and cannot travel through a vacuum", "The higher their frequency, the faster they travel in a vacuum", "They are waves formed by mechanical vibrations traveling through a medium"],
      "Electromagnetic fields are physical, and electromagnetic waves need no medium. All electromagnetic waves travel at c = 3×10⁸ m/s in a vacuum, regardless of frequency; higher frequency means shorter wavelength."),
    C("standard", "Which list orders electromagnetic waves from longest to shortest wavelength?", "Radio waves, infrared, ultraviolet, X-rays", ["Radio waves, ultraviolet, infrared, X-rays", "X-rays, ultraviolet, infrared, radio waves", "Infrared, radio waves, ultraviolet, X-rays"],
      "From longest to shortest wavelength, the electromagnetic spectrum is radio waves, infrared, visible light, ultraviolet, X-rays, and gamma rays. Shorter wavelength means higher frequency and greater photon energy."),
  ])

T("quantum", "Matter", "conceptual",
  "Know the experimental laws of blackbody radiation and learn Planck's quantum hypothesis, ε = hν: an object's emitted or absorbed energy can only be an integer multiple of a smallest unit. Become familiar with quantization in the microscopic world.",
  ["Know the quantum energy ε = hν and the meaning of Planck's constant", "Know how blackbody radiation intensity changes as temperature increases", "Estimate photon energy and photon count using ε = hν"],
  [("B3.3.6", "exact")],
  pre=[("em_wave", "hard"), ("J:temperature", "soft")],
  qs=[
    C("basic", "According to Planck's quantum hypothesis, what is the energy ε of a quantum of electromagnetic radiation with frequency ν? (h is Planck's constant)", "hν", ["h/ν", "hλ", "hν²"],
      "Quantum energy ε = hν is proportional to frequency. An object's emitted or absorbed energy can only be an integer multiple of hν; energy comes in discrete units."),
    N("basic", "Monochromatic light has a frequency of 5×10¹⁴ Hz. What is the energy of one photon in units of ×10⁻¹⁹ J? (Planck's constant h = 6.6×10⁻³⁴ J·s; enter a number only)", "3.3",
      "ε = hν = 6.6×10⁻³⁴ × 5×10¹⁴ = 3.3×10⁻¹⁹ J.", "round(6.6e-34*5e14/1e-19,2)"),
    C("standard", "As a blackbody's temperature increases, which statement about its radiation is correct?", "Radiation intensity increases at every wavelength, and the peak shifts toward shorter wavelengths", ["Radiation intensity decreases at every wavelength, and the peak shifts toward longer wavelengths",
      "Radiation intensity increases only at long wavelengths, and the peak stays in the same place", "Radiation intensity increases at every wavelength, and the peak shifts toward longer wavelengths"],
      "As temperature rises, the object's radiation intensifies and its color shifts from dark red through orange and yellow to white, showing that the peak wavelength gets shorter (frequency increases)."),
    C("standard", "A laser pointer emits light at 5×10¹⁴ Hz with an optical power of 3.3 mW. About how many photons does it emit per second? (h = 6.6×10⁻³⁴ J·s)", "1×10¹⁶ photons", ["1×10¹⁹ photons", "1×10¹³ photons", "1×10¹⁵ photons"],
      "Each photon has energy ε = hν = 3.3×10⁻¹⁹ J. The emitted energy per second is 3.3×10⁻³ J, so the photon count is n = 3.3×10⁻³ / 3.3×10⁻¹⁹ = 1×10¹⁶. Treating mW as W gives the incorrect result 1×10¹⁹."),
  ])
